"use client"; import {useState} from "react";
export default function Transactions(){const[type,setType]=useState("TRANSFER");const[amount,setAmount]=useState("");const[submitted,setSubmitted]=useState(false);return <main className="container section"><h1>Banking transactions</h1><div className="grid"><div className="card"><h2>New transaction</h2><label className="label">Transaction type</label><select className="input" value={type} onChange={e=>setType(e.target.value)}><option>TRANSFER</option><option>DEPOSIT</option><option>WITHDRAWAL</option></select><label className="label">Amount</label><input className="input" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/><label className="label">Description / destination</label><input className="input" placeholder="Account or transaction purpose"/><button className="btn btn-primary" onClick={()=>setSubmitted(true)}>Submit transaction</button>{submitted&&<div className="notice" style={{marginTop:15}}>Transaction submitted to the controlled workflow. A production API should validate limits, balance, authorization and fraud rules server-side.</div>}</div><div className="card"><h2>Recent activity</h2><table className="market-table"><tbody><tr><td>Deposit</td><td>₦500,000</td><td className="positive">Completed</td></tr><tr><td>Transfer</td><td>₦75,000</td><td className="positive">Completed</td></tr><tr><td>Withdrawal</td><td>₦30,000</td><td>Pending</td></tr></tbody></table></div></div></main>}